BEGIN TRANSACTION;
CREATE TABLE offres (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            date_collecte TEXT NOT NULL,
            hub_origine TEXT NOT NULL,
            destination_code TEXT,
            destination_nom TEXT,
            prix_vol_hub REAL,
            rabattement REAL,
            total_estime REAL,
            date_depart TEXT,
            lien TEXT
        , ville_depart TEXT NOT NULL DEFAULT 'Dakar');
DELETE FROM "sqlite_sequence";
COMMIT;